def get_attention_backend():
    """
    检测可用的 attention 后端，优先级:
    1. 环境变量 ATTENTION_BACKEND 强制指定 ('flash_attn', 'npu_flash', 'torch_sdpa')
    2. 自动检测: flash_attn > npu_flash > torch_sdpa
    """
    env_backend = os.environ.get('ATTENTION_BACKEND', '').strip().lower()
    if env_backend in ('flash_attn', 'npu_flash', 'torch_sdpa'):
        return env_backend
    try:
        import flash_attn  # noqa: F401
        return 'flash_attn'
    except ImportError:
        pass
    try:
        import torch_npu  # noqa: F401
        if hasattr(torch_npu, 'npu_fusion_attention'):
            return 'npu_flash'
    except ImportError:
        pass
    return 'torch_sdpa'

ATTENTION_BACKEND = get_attention_backend()

